// Real host/modules with synchronous fake I/O. No socket or simulator.
#include "Runtime.h"
#include <algorithm>
#include <cmath>
#include <functional>
#include <iostream>
#include <limits>
#include <map>
#include <stdexcept>
#include <vector>
using namespace mavmoos::runtime;
namespace {
void require(bool value,const char* why){if(!value)throw std::runtime_error(why);}
mavlink_message_t decode(const uint8_t* bytes,std::size_t count){mavlink_message_t m{},b{};mavlink_status_t s{},r{};bool found=false;for(std::size_t i=0;i<count;++i)if(mavlink_frame_char_buffer(&b,&s,bytes[i],&m,&r)==MAVLINK_FRAMING_OK)found=true;require(found,"encoded packet invalid");return m;}
int rateId(const mavlink_message_t& m){if(m.msgid!=76)return -1;mavlink_command_long_t c{};mavlink_msg_command_long_decode(&m,&c);return c.command==511?int(c.param1):-1;}
struct Sent{mavlink_message_t message;double at;bool accepted;};
struct Rig {
 double time=100;std::vector<Sent> sent;std::map<int,unsigned> rate_calls;std::map<std::string,std::string> latest;
 bool fail_first=false,fail_all=false;Runtime host;
 explicit Rig(const std::string& telemetry,bool simulation=true,bool shadow=false):host(
  [&](const auto& k,const auto& text,double,bool numeric){if(!numeric)latest[k]=text;},
  [&](const uint8_t* p,std::size_t n){auto m=decode(p,n);int id=rateId(m);bool accepted=true;if(id>=0){unsigned attempt=++rate_calls[id];accepted=!(fail_all||(fail_first&&id==33&&attempt==1));}sent.push_back({m,time,accepted});return accepted;},simulation,shadow,[&]{return time;}){require(host.load(telemetry),"load telemetry");fresh();}
 void fresh(bool flight=false){mavlink_message_t m{};mavlink_status_t c{};mavlink_msg_heartbeat_pack_status(1,1,&c,&m,2,3,flight?128:0,4,4);host.message(m,time);
  if(flight){mavlink_msg_global_position_int_pack_status(1,1,&c,&m,0,423584560,-710875890,15000,5000,0,100,0,9000);host.message(m,time);mavlink_msg_extended_sys_state_pack_status(1,1,&c,&m,0,2);host.message(m,time);mavlink_home_position_t h{};h.latitude=423584560;h.longitude=-710875890;h.altitude=10000;mavlink_msg_home_position_encode_status(1,1,&c,&m,&h);host.message(m,time);mavlink_ekf_status_report_t e{};e.flags=51;mavlink_msg_ekf_status_report_encode_status(1,1,&c,&m,&e);host.message(m,time);}}
 void run(unsigned steps=30){for(unsigned i=0;i<steps;++i){time=100.01+i*.11;fresh();host.tick(time);}}
 unsigned rate(int id,bool accepted_only=false)const{return std::count_if(sent.begin(),sent.end(),[&](const auto& s){return rateId(s.message)==id&&(!accepted_only||s.accepted);});}
 unsigned count(unsigned id)const{return std::count_if(sent.begin(),sent.end(),[&](const auto& s){return s.message.msgid==id;});}
 void bound(const std::function<void(const mavlink_message_t&,double)>& proof){host.setBoundedSend([&,proof](const uint8_t* p,std::size_t n,double expires,const Runtime::SendEligibility& eligible){auto m=decode(p,n);proof(m,expires);if(time>=expires||!eligible(time))return false;sent.push_back({m,time,true});return true;});}
};
}
int main(int argc,char** argv){try{
 require(argc==4,"usage: stream_runtime_tests TELEMETRY CONTROL baseline|current");const std::string telemetry=argv[1],control=argv[2];
 if(std::string(argv[3])=="baseline"){Rig r(telemetry);r.fail_first=true;r.run();require(r.rate(33)==1&&r.rate(33,true)==0,"old lost-send baseline changed");std::cout<<"REPRODUCED old one-shot lost local rejection: msg33 attempts=1 accepted=0 after3.2s with fresh heartbeat\n";return 0;}
 unsigned groups=0;auto test=[&](const char* name,const auto& fn){fn();++groups;std::cout<<"PASS "<<name<<'\n';};
 test("local rejection retries and stops after acceptance",[&]{Rig r(telemetry);r.fail_first=true;r.run();require(r.rate(33)==2&&r.rate(33,true)==1,"local rejected stream never recovered or accepted work replayed");require(!r.host.navigationGranted()&&!r.host.controlBusy(),"stream setup granted/busied control");});
 test("rejected work exhausts fixed attempt budget",[&]{Rig r(telemetry);r.fail_all=true;r.run();require(!r.rate_calls.empty(),"no rate work");for(auto [id,n]:r.rate_calls)require(n==3&&r.rate(id,true)==0,"local retry budget wrong");});
 test("one protocol attempt per tick and bounded global pacing",[&]{Rig r(telemetry);r.fail_first=true;r.run();double previous=-1;for(const auto& s:r.sent)if(rateId(s.message)>=0){if(previous>=0)require(s.at-previous>=.1-1e-9,"burst stream requests");previous=s.at;}});
 test("ACK511 is not correlated stream application",[&]{Rig r(telemetry);r.fail_first=true;for(unsigned i=0;i<30;++i){r.time=100.01+i*.11;r.fresh();mavlink_message_t m{};mavlink_command_ack_t a{};a.command=511;a.result=MAV_RESULT_ACCEPTED;a.target_system=245;a.target_component=191;mavlink_msg_command_ack_encode(1,1,&m,&a);r.host.message(m,r.time);r.host.tick(r.time);}require(r.rate(33)==2&&r.rate(33,true)==1,"unmatched ACK changed local retry semantics");});
 test("RX_ONLY and shadow admit no send work",[&]{for(bool shadow:{false,true}){Rig r(telemetry,shadow,shadow);r.run();require(r.sent.empty()&&!r.host.navigationGranted(),"receive-only/shadow sent or acquired");}});
 test("original expiry survives endpoint proof",[&]{Rig r(telemetry);double original=0;r.bound([&](const auto& m,double expires){if(rateId(m)>=0){if(original==0)original=expires;require(expires==original,"stream expiry renewed");while(r.time+.5<original){r.time+=.5;r.fresh();}r.time=original+.01;r.fresh();}});r.time=100.01;r.fresh();r.host.tick(r.time);require(original>100&&r.rate(33,true)==0&&r.host.vehicle().heartbeat_valid,"expiry was not isolated from heartbeat loss");});
 test("reset plus fresh heartbeat cannot revive dequeued stream",[&]{Rig r(telemetry);bool once=false;r.bound([&](const auto& m,double){if(rateId(m)>=0&&!once){once=true;r.host.disconnect(r.time);r.fresh();}});r.time=100.01;r.fresh();r.host.tick(r.time);require(once&&r.rate(33,true)==0,"old stream crossed reset");r.time=100.2;r.fresh();r.host.tick(r.time);require(r.rate(33,true)==1,"fresh session could not request stream");});
 test("freshness is rechecked before a still-unexpired request",[&]{Rig r(telemetry);double original=0;r.bound([&](const auto& m,double expires){if(rateId(m)>=0){original=expires;r.time+=2.1;}});r.time=100.01;r.fresh();r.host.tick(r.time);require(original>r.time&&r.rate(33,true)==0&&!r.host.vehicle().heartbeat_valid,"stale heartbeat passed final send predicate before expiry");});
 test("locally rejected return crossing original expiry never retries",[&]{Rig r(telemetry);unsigned attempts=0;r.host.setBoundedSend([&](const uint8_t* p,std::size_t n,double expires,const Runtime::SendEligibility& eligible){if(!eligible(r.time))return false;if(rateId(decode(p,n))>=0){++attempts;r.time=expires+.01;return false;}return true;});r.time=100.01;r.fresh();r.host.tick(r.time);const auto event=r.latest.at("MAVMOOS_STREAM_REQUEST_RESULT");require(attempts==1&&event.find("\"local_result\":\"NOT_ACCEPTED\"")!=std::string::npos&&event.find("\"state\":\"EXPIRED\"")!=std::string::npos,"expired local rejection became retryable");});
 test("configuration change fences an encoded stream",[&]{Rig r(telemetry);bool once=false;r.bound([&](const auto& m,double){if(rateId(m)>=0&&!once){once=true;r.host.configure("lat_origin","42.358456");}});r.time=100.01;r.fresh();r.host.tick(r.time);require(once&&r.rate(33,true)==0,"old stream crossed configuration generation");r.time=100.2;r.fresh();r.host.tick(r.time);require(r.rate(33,true)==1,"new configuration did not request stream");});
 test("actual acceptance followed by reset is reported without reviving work",[&]{Rig r(telemetry);bool once=false;r.host.setBoundedSend([&](const uint8_t* p,std::size_t n,double,const Runtime::SendEligibility& eligible){if(!eligible(r.time))return false;auto m=decode(p,n);r.sent.push_back({m,r.time,true});if(rateId(m)>=0&&!once){once=true;r.host.disconnect(r.time);r.fresh();}return true;});r.time=100.01;r.fresh();r.host.tick(r.time);const auto event=r.latest.at("MAVMOOS_STREAM_REQUEST_RESULT");require(once&&r.rate(33,true)==1&&event.find("\"local_result\":\"LOCAL_ACCEPTED\"")!=std::string::npos&&event.find("\"matched_current\":false")!=std::string::npos,"old accepted receipt concealed or applied to fresh epoch");require(r.latest.at("MAVMOOS_STREAM_STATUS").find("\"started\":false")!=std::string::npos,"old completion admitted a new plan");});
 test("accepted late receipt stays terminal with original bound",[&]{Rig r(telemetry);r.host.setBoundedSend([&](const uint8_t* p,std::size_t n,double expires,const Runtime::SendEligibility& eligible){if(!eligible(r.time))return false;auto m=decode(p,n);r.sent.push_back({m,r.time,true});if(rateId(m)>=0)r.time=expires+.01;return true;});r.time=100.01;r.fresh();r.host.tick(r.time);const auto event=r.latest.at("MAVMOOS_STREAM_REQUEST_RESULT");require(r.rate(33,true)==1&&event.find("\"local_result\":\"LOCAL_ACCEPTED\"")!=std::string::npos&&event.find("\"matched_current\":true")!=std::string::npos&&event.find("\"late\":true")!=std::string::npos,"late acceptance was hidden or made retryable");require(r.latest.at("MAVMOOS_STREAM_STATUS").find("\"accepted_receipt_late\":1")!=std::string::npos,"late receipt not diagnosed");});
 test("post-return clock fault preserves acceptance but invalidates receipt time",[&]{for(double bad:{100.0,std::numeric_limits<double>::quiet_NaN()}){Rig r(telemetry);bool once=false;r.host.setBoundedSend([&](const uint8_t* p,std::size_t n,double,const Runtime::SendEligibility& eligible){if(!eligible(r.time))return false;auto m=decode(p,n);r.sent.push_back({m,r.time,true});if(rateId(m)>=0&&!once){once=true;r.time=bad;}return true;});r.time=100.01;r.fresh();r.host.tick(r.time);const auto event=r.latest.at("MAVMOOS_STREAM_REQUEST_RESULT");require(once&&r.rate(33,true)==1&&event.find("\"local_result\":\"LOCAL_ACCEPTED\"")!=std::string::npos&&event.find("\"clock_valid\":false")!=std::string::npos&&event.find("\"post_return_at\":null")!=std::string::npos&&event.find("\"late\":null")!=std::string::npos,"bad post-return clock concealed acceptance or supplied false timing");require(!r.host.vehicle().heartbeat_valid&&!r.host.navigationGranted(),"clock fault retained session/authority");require(r.latest.at("MAVMOOS_STREAM_STATUS").find("\"state\":\"CLOCK_FAULT\"")!=std::string::npos,"stream clock fault was hidden");}});
 test("control precedes fair single shared protocol slot",[&]{Rig r(telemetry);require(r.host.load(control),"control module");r.host.configure("control_native_actions","false");r.host.configure("control_helm","false");r.fresh(true);require(r.host.acquireNavigation("control"),"grant");
  for(unsigned i=0;i<4;++i){ParameterRequest p;p.id="p"+std::to_string(i);p.name="FRAME_CLASS";p.expires=102;require(r.host.parameter(p),"parameter queue");MissionRequest m;m.id="m"+std::to_string(i);m.operation_id="read";m.action=MissionAction::RequestList;m.expires=102;m.operation_expires=105;require(r.host.mission(m),"mission queue");}
  for(unsigned step=0;step<30;++step){r.time=100.01+step*.02;r.fresh(true);require(r.host.navigation({90,1,5,r.time+.4}),"target");auto before=r.sent.size();r.host.tick(r.time);unsigned bulk=0;bool seen_bulk=false;for(std::size_t i=before;i<r.sent.size();++i){const auto& m=r.sent[i].message;if(m.msgid==20||m.msgid==43||rateId(m)>=0){++bulk;seen_bulk=true;}if(m.msgid==84)require(!seen_bulk,"bulk preceded control");}require(bulk<=1,"bulk budget doubled");}
  require(r.count(20)==4&&r.count(43)==4&&r.rate(33,true)==1,"protocol class starved");require(r.count(84)>=4&&r.host.navigationGranted(),"rate work interrupted navigation");});
 std::cout<<"PASS "<<groups<<" real Runtime stream-service groups; fake I/O only\n";return 0;
}catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
